            verdict: 'pass',
            acceptance: [
              { id: 'A1', result: 'passed', reason: 'The retry verified the workflow.' },
            ],
            risks: [],
            summary: 'The independent retry passed.',
          },
        },
      },
      root,
      'verifier-retry-result',
      'verifier-session-4',
    );
    expect(run.waits.at(-1)).toMatchObject({ stepId: 'verify.confirm', status: 'pending' });
